rows('precursors',[
('mwnt','Multiwalled carbon nanotubes','MWNTs were purchased from MER Corporation. The nanotubes serve as the scaffold and, after oxidation, as bulky coordination ligands and growth terminators. Mass, dimensions, wall-count distribution and supplied grade are not given. This is a CdTe/MWNT composite, not a CdSe synthesis.',2,'Nanotube Processing and Heterostructure Synthesis',['oxidation','growth']),
('oxidants','Permanganate and sulfuric acid','A vigorous KMnO₄/H₂SO₄ treatment, citing reference 35, precedes acid washing. The paper does not supply oxidant masses, acid concentration, liquid volume, temperature or duration. The cited procedure is not silently imported as an executed recipe.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('hcl','Hydrochloric-acid treatment','A 35% HCl solution follows the permanganate/sulfuric-acid treatment. The percentage basis, quantity, treatment time and temperature are unreported.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('hf','Hydrofluoric-acid treatment','A 10% HF solution follows the HCl treatment. The percentage basis, quantity, treatment time and temperature are unreported; this is a sequential processing step, not a combined HCl/HF stock.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('water','Distilled-water washing','Processed tubes are washed extensively with distilled water before drying. No number of washes, volume or endpoint is specified.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('surface-groups','Oxidized nanotube surface','The authors expect a mixture of carboxylic-acid, alcohol and ketone functionalities at opened ends and exposed sidewall defects. Exact site populations, molecular connectivity and surface stoichiometry are not determined; illustrative groups must not become an atomically resolved surface model.',2,'Oxygenated functional groups',['oxidation','growth','mechanisms'],'model_context','author_interpretation'),
('cdo','Cadmium precursor','CdO is mixed with oxidized MWNTs and tetradecylphosphonic acid. CdO mass, amount, purity and vendor are not specified. The source proposes Cd coordination to oxygenated surface groups; no isolated coordination compound or exact stoichiometry is characterized.',2,'Heterostructure synthesis',['growth']),
('tdpa','Tetradecylphosphonic acid','TDPA is used in a substoichiometric amount so some Cd can coordinate to nanotube oxygen groups, particularly acid and alcohol groups. Neither a numerical Cd:TDPA ratio nor absolute TDPA charge is supplied. It is a secondary nanocrystal ligand, omitted in Figure 8 for clarity.',2,'Heterostructure synthesis',['growth','mechanisms']),
('topo','Trioctylphosphine oxide','TOPO is the medium used while the oxidized-MWNT/CdO/TDPA mixture is heated. Its quantity, purity and water content are not reported.',2,'Heterostructure synthesis',['growth']),
('te-top','Tellurium solution in trioctylphosphine','A Te solution in TOP is injected at 300 °C. Te quantity, TOP quantity, stock concentration, preparation conditions and injected volume are not supplied. The wording does not independently establish an isolated TOPTe molecular structure or a measured stock speciation.',2,'Heterostructure synthesis',['growth'],'method_context'),
('argon','Argon atmosphere','Argon is stated for the 320 °C precursor-heating stage. Flow rate, pressure, vessel closure and a stage-by-stage atmosphere log are absent.',2,'Heterostructure synthesis',['growth'],'method_context'),
('toluene','Toluene for workup and optical comparison','Five millilitres of toluene are added after cooling to 50 °C; additional copious toluene washes remove free nanocrystals. The 5 mL dose is not the total washing volume. CdTe washings are also measured in toluene for the optical comparison.',2,'Workup',['growth','uv-visible']),
('methanol','Methanol antisolvent','Methanol addition precipitates solids containing both nanotube-associated and free CdTe. Its dose and addition rate are unreported.',2,'Workup',['growth']),
('ptfe','PTFE filtration membrane','A 0.2 µm PTFE membrane retains the solid heterostructures while toluene washing removes unbound CdTe. The pore size is an apparatus specification, not a nanocrystal diameter.',2,'Workup',['growth'],'method_context'),
('ethanol','Ethanol for microscopy specimens','TEM/HRTEM specimens are prepared by drying droplets from an ethanolic sample solution onto lacey-carbon-coated copper grids. This is analytical sample preparation, not an additional synthesis solvent.',3,'Electron Microscopy',['electron-microscopy'],'method_context'),
('dmf','Dimethylformamide for electronic spectroscopy','The nanotube–nanocrystal heterostructure is dispersed by sonication in DMF for UV–visible analysis. Sonication duration, power and concentration are not supplied.',4,'Optical Spectroscopy continuation',['uv-visible'],'method_context'),
('analytical-supports','Analytical substrates and optical accessories','Microscopy uses copper grids and lacey carbon; SEM grids are held over a Be plate. XPS uses conductive double-sided tape on stainless-steel holders. Optical measurements use quartz cells, and infrared uses a ZnSe ATR accessory. These are supports or instrument components, not growth precursors.',3,'Electron Microscopy, XPS and Optical Spectroscopy',['electron-microscopy','sem','xps','uv-visible','infrared'],'method_context'),
('stocks-missing','Stock and concentration limits','No molar concentration is specified for the Te/TOP stock or the reaction mixture. Except for the two percentage acid solutions and the 5 mL workup dose, absolute reagent and solvent charges are absent. They remain missing rather than inferred from the cited Peng protocols.',2,'Complete synthesis paragraph',['growth'],'curator_interpretation','reviewed_source_limitation'),
])
more('tdpa',8,'Figure 8 caption');more('toluene',4,'Optical Spectroscopy continuation');more('analytical-supports',4,'Infrared instrument description')
rows('protocol',[
('oxidative-treatment','Oxidative nanotube processing','Apply the reported vigorous KMnO₄/H₂SO₄ treatment to the purchased MWNTs, following the source’s reference to method 35. It is intended to remove most catalyst metal, including iron, and a substantial fraction of amorphous carbon. The supplied article does not provide a complete timed or quantitative oxidation recipe.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('hcl-treatment','Successive HCl processing','Process the oxidized nanotubes with 35% HCl after the permanganate/sulfuric-acid stage. Preserve the stated order; no duration, temperature or solution-to-solid ratio is supplied.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('hf-treatment','Successive HF processing','Follow HCl processing with 10% HF. The source describes successive treatments; it does not report a mixed-acid recipe or quantitative extent of dissolution.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('water-wash','Wash processed nanotubes','Wash extensively with distilled water. No number of cycles, pH endpoint or washing volume is specified.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('dry-nanotubes','Dry processed nanotubes','Heat the washed nanotubes in a drying oven at 150 °C. Drying duration and atmosphere are not stated.',2,'Nanotube processing',['oxidation','growth'],'method_context'),
('precursor-mixing','Prepare the growth mixture','Mix the oxygenated MWNTs with CdO and a substoichiometric amount of TDPA in TOPO. The precursor-quantity and stock fields remain explicitly incomplete.',2,'Heterostructure synthesis',['growth'],'method_context'),
('precursor-heating','Heat the cadmium-containing mixture','Heat to 320 °C under argon with vigorous stirring. Heating rate, dwell time, stirring speed and pressure are not supplied. The authors propose Cd binding to nanotube oxygen groups; the schematic represents this rationale rather than a measured reaction intermediate.',2,'Heterostructure synthesis',['growth'],'method_context'),
('te-injection','Inject the Te/TOP solution','Inject the Te solution in TOP at 300 °C. The source distinguishes the 320 °C precursor treatment from the 300 °C injection temperature but does not specify the intervening cooling rate, injection volume or injection duration.',2,'Heterostructure synthesis',['growth'],'method_context'),
('growth','Grow CdTe on nanotubes','Allow nanocrystals to grow at 250 °C for 20 min. Exact temperature recovery and cooling profiles, aliquot series and in situ growth rates are absent.',2,'Heterostructure synthesis',['growth'],'method_context'),
('cooling','Terminate heating and cool','Remove the heat source after the 20 min growth period and cool to 50 °C before adding toluene. A cooling rate or duration is not stated.',2,'Heterostructure synthesis',['growth'],'method_context'),
('toluene-addition','Add the workup solvent','Add 5 mL of toluene at 50 °C. This is the reported initial workup solvent addition, distinct from later unquantified toluene washing.',2,'Heterostructure synthesis',['growth'],'method_context'),
('precipitation','Precipitate the solids','Add methanol to initiate precipitation. The recovered solid initially contains functionalized tubes and nanocrystals not attached to tubes; precipitation alone does not establish a purified composite.',2,'Heterostructure synthesis',['growth'],'method_context'),
('filtration','Collect on a PTFE membrane','Filter the solid residue through a 0.2 µm PTFE membrane. Filtration pressure, membrane area and collection duration are unreported.',2,'Heterostructure synthesis',['growth'],'method_context'),
('toluene-washing','Remove free nanocrystals','Wash with copious toluene to remove nanocrystals unbound to the tubes. Retain the functionalized heterostructures on the membrane and keep the washings analytically distinct.',2,'Heterostructure synthesis',['growth','free-nanocrystals'],'method_context'),
('product-drying','Dry the isolated heterostructures','Dry the membrane-retained heterostructures for characterization. The final drying conditions, yield, recovery efficiency and storage protocol are not stated.',2,'Heterostructure synthesis',['growth'],'method_context'),
('tem-preparation','TEM and HRTEM specimen preparation','Dry sample droplets from an ethanolic solution on 300-mesh copper grids coated with lacey carbon. The source does not supply droplet volume, dispersion concentration or a unique batch identifier for each micrograph.',3,'Electron Microscopy',['electron-microscopy'],'method_context'),
('tem-acquisition','Low-resolution transmission microscopy','Use the Philips CM12 TEM at 120 kV for low-resolution imaging; the instrument is equipped with EDAX capability. Low-resolution acquisition settings are separate from the 200 kV HRTEM settings.',3,'Electron Microscopy',['electron-microscopy','eds'],'method_context'),
('hrtem-acquisition','High-resolution transmission microscopy','High-resolution images were obtained on a JEOL 2010F HRTEM at 200 kV, with an Oxford INCA EDS system. No selected-area diffraction pattern, calibrated lattice-spacing table or electron-dose series is supplied.',3,'Electron Microscopy',['electron-microscopy','eds'],'method_context'),
('sem-preparation','SEM specimen mounting','Drop-dry the SEM samples onto copper grids, then hold them over a Be plate in a homemade sample holder. This mounting configuration is not a product constituent.',3,'Electron Microscopy',['sem'],'method_context'),
('sem-acquisition','Scanning electron microscopy','Image on a Leo 1550 field-emission instrument using 2–10 kV accelerating voltage and a 2 mm working distance. Panel-specific voltages within that range are not assigned.',3,'Electron Microscopy',['sem'],'method_context'),
('eds-acquisition','Energy-dispersive X-ray analysis','EDAX and Oxford INCA EDS instrument capabilities are reported. Cd/Te identification supports the SEM/TEM product interpretation, and Figure 4a includes an EDS spectrum. The article does not uniquely assign that inset to one detector configuration or give acquisition time and quantitative calibration.',3,'Electron Microscopy',['eds'],'method_context'),
('xps-mounting','XPS mounting and vacuum','Attach samples to stainless-steel holders with conductive double-sided tape. Use a Kratos DS800 surface-analysis system with a hemispherical analyzer and a base pressure of approximately 5 × 10⁻⁹ torr.',3,'X-ray Photoelectron Spectroscopy',['xps'],'method_context'),
('xps-survey','Initial XPS acquisition','The initial spectra used a Mg Kα source, 80 eV pass energy and 0.75 eV steps. Source power, charge neutralization and binding-energy calibration procedure are not specified.',3,'X-ray Photoelectron Spectroscopy',['xps'],'method_context'),
('xps-high-resolution','High-resolution XPS acquisition','Collect high-resolution spectra at 10 eV pass energy in 0.1 eV steps. The original figure includes measured and fitted-looking traces, but no full peak-fitting model, uncertainty or numerical area fractions is supplied.',3,'X-ray Photoelectron Spectroscopy',['xps'],'method_context'),
('xrd-acquisition','Powder X-ray diffraction','Use a Scintag diffractometer in Bragg configuration with Cu Kα radiation, λ = 1.54 Å. Scan rate, step size, instrument broadening correction and a structural refinement are not supplied.',3,'X-ray Diffraction',['xrd'],'method_context'),
('uv-preparation','UV–visible sample preparation','Measure CdTe nanocrystal washings dissolved in toluene and the nanotube–nanocrystal heterostructure dispersed by sonication in DMF. The two spectra therefore have different specimen and solvent contexts; identical concentrations are not established.',3,'Optical Spectroscopy and p. 4 continuation',['uv-visible'],'method_context'),
('uv-acquisition','UV–visible acquisition','Use a Thermospectronics UV1 at high resolution with 10 mm path-length quartz cells. Numerical spectral resolution, blank subtraction and extinction normalization are unreported.',3,'Optical Spectroscopy',['uv-visible'],'method_context'),
('ir-acquisition','Infrared acquisition','Infrared spectra were acquired on a ThermoNicolet Nexus 670 with a ZnSe single-reflectance ATR accessory. The supplied SI spectrum is explicitly for oxidized MWNTs, not a CdTe composite IR spectrum. Resolution, number of scans and individual peak assignments are unreported.',4,'Optical Spectroscopy',['infrared'],'method_context'),
('raman-acquisition','Raman acquisition','Use a Jasco Ventuno micro-Raman instrument, a 200 µm confocal aperture, 785 nm diode-laser excitation and 10 mW laser power. No spot size, acquisition temperature or per-spectrum integration time is reported.',4,'Optical Spectroscopy',['raman'],'method_context'),
('control-scope','Oxidation-control scope','The authors report successive growth comparisons with pristine/raw and mildly oxidized tubes. Their abbreviated discussion does not give independent complete control recipes. Oxygen content and coverage comparisons remain observations, not additional fully parameterized synthesis routes.',8,'Oxidation controls',['oxidation-controls'],'curator_interpretation','reviewed_source_limitation'),
])
more('eds-acquisition',6,'Figure 4a inset');more('uv-preparation',4,'Optical Spectroscopy continuation');more('ir-acquisition',1,'Infrared spectrum heading',role='si')
rows('structures',[
('purification-evidence','Removal of catalyst contamination','XPS and EDS were reported to find remaining catalyst metal below detectable limits after processing. This is a method-dependent nondetection claim, not proof of zero metal or a quantified detection limit. The visible clean-tube comparison is retained.',2,'Nanotube processing',['oxidation','electron-microscopy','eds','xps']),
('figure1','Pristine and oxidized nanotube structure','Figure 1 compares pristine unprocessed MWNT sidewalls, a clean processed tube, an opened oxidized tip and serrated etched edges. Scale bars are 20 nm (a), 125 nm (b), 7 nm (c) and 8 nm (d). The arrows identify exposed wall regions; oxygen functional groups are inferred rather than atomically resolved.',3,'Figure 1',['electron-microscopy','oxidation']),
('oxidation-morphology','Oxidation-induced morphology','Aggressive oxidation opens caps and removes part of the outer wall, exposing serrated edges and defect sites. Pristine walls show a more continuous graphite lattice. The source does not report a numerical fraction of opened tubes or removed layers.',4,'Microscopy Characterization',['electron-microscopy','oxidation']),
('figure2-sem','SEM: tip-associated crystals and junctions','Figure 2a shows a particle near a tube tip, while Figure 2b shows a nanocrystal-mediated junction involving nanotube bundles. Arrows mark CdTe; scales are 100 and 200 nm. Cd and Te EDS signals support the assignment.',4,'Figure 2a,b',['sem','eds','growth']),
('figure2-tem','TEM: sidewall coverage and junctions','Figure 2c shows sidewall coverage on a MWNT bundle, Figure 2d crystals along sidewalls and near a tip, and Figure 2e crystal-mediated tube junctions. The respective scale bars are 180, 75 and 112 nm. No quantitative coverage fraction is extracted from these selected images.',4,'Figure 2c–e',['electron-microscopy','growth']),
('figure3-interface','HRTEM: CdTe–nanotube interfaces','Figure 3a resolves crystalline fringes at a nanotube–nanocrystal interface; its inset is a different composite, not a magnified view of the same specimen. Both scale bars are 5 nm. The paper does not tabulate lattice spacings or determine an atom-resolved bonding registry.',5,'Figure 3a',['electron-microscopy','growth']),
('figure3-sites','HRTEM: tip, defect and edge growth','Figure 3b shows an elongated crystal at an opened tip (20 nm bar); 3c shows growth at an etched sidewall defect (5 nm); 3d shows crystals near exposed outer-wall edges (10 nm). Arrows preserve the authors’ proposed attachment/nucleation-site interpretation.',5,'Figure 3b–d',['electron-microscopy','growth']),
('figure4-junction','HRTEM: nanocrystal-mediated junction','Figure 4a shows a crystal between and attached to two nanotube bundles. Arrow sets delimit irregular crystals and the inset supplies EDS evidence. Figure 4b,c show extensive sidewall coverage; scale bars are 20, 10 and 10 nm, respectively.',6,'Figure 4',['electron-microscopy','eds','growth']),
('eds-elements','Elemental evidence and scope','The text reports Cd, Te and P in the heterostructures, with phosphorus attributed to secondary TDPA ligands. The plotted inset labels C, O, Cu, Cd and Te; a distinct P label is not supplied in that inset. No elemental ratios, uncertainties or map are given, and Cu support signals are not evidence for a Cu-containing synthesis product.',6,'EDS discussion and Figure 4a inset',['eds']),
('eds-unit-conflict','EDS energy-axis ambiguity','The Figure 4 caption calls the EDS horizontal axis energy in eV, while the inset scale runs approximately 0–10. The reader preserves the literal caption and original axis without silently changing units to keV or digitizing calibrated elemental energies.',6,'Figure 4 caption and inset',['eds'],'curator_interpretation','source_evidence_conflict'),
('crystal-phase','CdTe crystal-phase assignment','HRTEM and XRD are interpreted as predominantly wurtzite CdTe, with some zinc-blende crystals and/or zinc-blende stacking faults likely. Overlapping peaks limit separation. The source does not support a phase-pure label, quantitative polymorph fractions or a uniquely refined unit cell.',6,'Crystal structure discussion',['electron-microscopy','xrd']),
('xrd-indexing','Figure 5ii: indexed diffraction','The XRD graph spans labeled 2θ values from 20° to 70° with arbitrary intensity. Black labels identify wurtzite CdTe: the low-angle group 100/002/101, then 110, 103 and 200. Red MWNT labels are 002, 101 and 004. The nearby CdTe 103 and nanotube 101 labels are separate source assignments.',7,'Figure 5ii',['xrd']),
('xrd-broadening','Diffraction broadening','The authors attribute broader peaks relative to bulk material to finite nanocrystal size. No Scherrer size, peak-width table, instrument correction or Rietveld fit is reported here.',8,'Additional Structural Characterization',['xrd'],'model_context','author_interpretation'),
('particle-dimensions','Size and shape of attached crystals','The reported long axis of in situ-grown nanocrystals ranges from 1 to 9 nm and their aspect ratio from 1 to 5. These are ensemble source ranges, not one-to-one paired particle measurements or a monodisperse diameter distribution.',8,'Nanocrystal size and shape discussion',['electron-microscopy','growth']),
('free-particle-size','Free particles and the no-tube reference','The page 7 discussion describes washed-away free particles as relatively monodisperse and quasi-spherical around 5 nm. Page 9 states the washings are less monodisperse than quasi-spherical approximately 5 nm crystals grown without nanotube ligands. Preserve these distinct source comparisons; do not assign a measured narrow size histogram or a complete no-tube recipe.',7,'Free-nanocrystal discussion continuing on pp. 8–9',['free-nanocrystals'],'curator_interpretation','source_comparison_scope'),
('oxidation-coverage','Oxidation level and attached-particle coverage','Highly oxidized MWNTs contain approximately 5–6 atomic % oxygen by XPS and show high coverage at ends and many sidewall sites. Mildly oxidized tubes with approximately 1–2 atomic % oxygen show sparse coverage; pristine unoxidized tubes show few, if any, coordinated crystals. No quantitative coverage-density calibration is supplied.',8,'Oxidation controls',['oxidation-controls']),
('surface-xps','XPS surface chemistry','Figure 5i presents C 1s, O 1s, Cd 3d₅/₂ and Te 3d₅/₂ high-resolution spectra. C 1s has a high-binding-energy asymmetry assigned to carboxylic-acid/carboxylate-like structures. Cd is assigned to CdTe at 405.22 eV. Detailed carbon and oxygen component fractions are not reported.',8,'XPS discussion and Figure 5i',['xps']),
('figure5-xps','Figure 5i: original binding-energy axes','The four descending binding-energy axes retain C ticks 295/290/285 eV, O ticks 534/532/530/528 eV, Cd ticks 408/406/404/402 eV, and Te ticks 580/578/576/574/572/570 eV. Vertical intensity is arbitrary without numerical ticks. Original red traces and black fit traces are retained; no extra peak energies or fitted component areas are digitized.',7,'Figure 5i',['xps']),
('teo3','Literal tellurium-oxide attribution','The source attributes Te 3d₅/₂ features to “TeO₃” and inadequate CdTe passivation. This literal assignment is retained rather than silently substituted with another tellurium oxide. It does not establish a separately prepared bulk oxide phase or quantitative oxidation fraction.',8,'XPS and surface-passivation paragraph',['xps','mechanisms'],'curator_interpretation','source_assignment_limit'),
('structure-limit','Atomic-structure and sample limits','The supplied article provides micrographs, an EDS inset and diffraction/XPS curves, but no CIF, refined atomic coordinates, SAED pattern, complete lattice-spacing table or resolved CdTe/MWNT interfacial bonding geometry. The Figure 8 spheres are a schematic, not an experimentally reconstructed crystal structure.',6,'Figures 3–5 and Figure 8',['source-context'],'curator_interpretation','reviewed_source_limitation'),
])
more('purification-evidence',5,'Absence of extraneous catalyst particles');more('crystal-phase',7,'Figure 5ii caption');more('crystal-phase',8,'XRD discussion');more('surface-xps',7,'Figure 5i');more('free-particle-size',9,'Electronic-spectrum interpretation')
rows('properties',[
('raman-cdte','CdTe Raman band','The heterostructure has a longitudinal-optic-type band at 166 cm⁻¹ under 785 nm excitation, absent from the oxidized-MWNT precursor spectrum. The source compares its downshift and broadening with a cited bulk CdTe peak at 170 cm⁻¹. The bulk value is a literature comparison, not a separately measured bulk spectrum in this paper.',8,'Raman discussion',['raman']),
('raman-carbon','Nanotube Raman bands','Both precursor and heterostructure spectra contain a G-mode band near 1590 cm⁻¹ and a weaker disorder-associated D band in the 1290–1320 cm⁻¹ range. No numerical D/G intensity ratio, linewidth or fitted disorder concentration is supplied.',8,'Raman discussion continuing on p. 9',['raman']),
('figure6','Figure 6: original Raman comparison','The upper blue trace represents oxidized/purified precursor MWNTs and the lower red trace the CdTe/MWNT product. The horizontal axis is wavenumber with labeled ticks at 1000–4000 cm⁻¹; the full original low-wavenumber region is retained. Intensity is arbitrary and the vertically offset traces do not provide a calibrated absolute-intensity ratio.',7,'Figure 6',['raman']),
('uv-heterostructure','Electronic spectrum of the heterostructure','The heterostructure spectrum is featureless and has no resolved CdTe exciton. The source attributes this to nanotube background absorption and variation in attached-crystal size and shape; it is not proof that CdTe is absent or a measured bandgap.',9,'Electronic spectrum discussion',['uv-visible']),
('uv-washings','Electronic spectrum of the washings','The toluene washings show greater heterogeneity than the separate approximately 5 nm quasi-spherical no-tube comparison. The authors propose some crystals detached from nanotubes at different growth stages. Detachment timing is a hypothesis, not a measured kinetic sequence.',9,'Electronic spectrum discussion',['uv-visible','free-nanocrystals'],'model_context','author_interpretation'),
('figure7','Figure 7: source electronic spectra','The lower red curve is from CdTe washings and the upper green curve is associated with the CdTe/MWNT heterostructure. The graph has labeled wavelength ticks from 300 to 1000 nm and arbitrary intensity; the green trace terminates earlier than the red trace. No missing wavelength segment, numerical absorbance table or exciton peak is reconstructed.',8,'Figure 7',['uv-visible']),
('si-ir','Supporting information: oxidized-MWNT infrared spectrum','The matched one-page SI supplies a single unnumbered IR trace of oxidized multiwalled nanotubes. The x-axis is wavenumber (cm⁻¹), descending through labeled ticks 2000, 1800, 1600, 1400, 1200, 1000 and 800; intensity is arbitrary. The paper gives no peak table or individual assignments. Peaks are preserved visually without inventing exact frequencies, signs, baseline treatment or a CdTe-product spectrum.',1,'Full SI spectrum and heading',['infrared'],'source_cohort','reported_source_fact','si'),
('property-limits','Unreported optical and device properties','No photoluminescence, quantum yield, excited-state lifetime, electrical transport, junction resistance, photovoltaic efficiency or device performance is measured in the supplied main article or SI. Applications and quantum-confinement arguments remain proposals or interpretations.',9,'Conclusions and complete supplied source',['source-context'],'curator_interpretation','reviewed_source_limitation'),
])
more('raman-carbon',9,'Continuation of Raman discussion')
rows('intuition',[
('assembly-context','Chemical recognition for nanotube assembly','The source motivates controlled CNT architectures and molecular-scale interconnects, contrasting chemical assembly with biological recognition, lithography, nanotube suspensions and patterned-substrate CVD. Broad computing, storage, sensing, drug-delivery, textile and light-harvesting applications are background possibilities, not tested outcomes here.',1,'Introduction',['source-context'],'cited_context','literature_context'),
('chemistry-context','Context of nanotube functionalization','Prior approaches target ends, defects, sidewalls and interiors through covalent chemistry, π stacking, dangling groups or macromolecular wrapping. Examples include BN coatings, carbide reactions and Si nanowire growth. These cited materials and procedures are not additional synthesis records from this experiment.',1,'Introduction continuing on p. 2',['source-context'],'cited_context','literature_context'),
('prior-cdse','Earlier CdSe/TiO₂ attachment work','The paper cites earlier CdSe and TiO₂–nanotube assembly using thiol/ligand functionalization and carbodiimide-mediated attachment, including EDC, 1-ethyl-3-(3-dimethylaminopropyl)carbodiimide hydrochloride, and 11-aminoundecanoic acid in the cited context. These reagents are not used in the present CdTe growth protocol. The authors describe that prior approach as favoring discrete, disordered ball-and-stick structures.',2,'Prior attachment strategies, references 28–31',['source-context'],'cited_context','literature_context'),
('coordination-context','Nanotubes as coordination ligands','Earlier bulky metal coordination complexes and Ru-functionalized nanotube T/Y junctions motivate using oxygenated MWNTs as ligands and growth templates. Solubility, catalyst recovery and homogeneous-catalysis claims belong to the cited systems rather than a measured property of the present composite.',2,'Coordination context, references 32–34',['source-context'],'cited_context','literature_context'),
('tdpa-competition','Why limit the small-molecule ligand','The stated rationale for substoichiometric TDPA is to leave some Cd available to bind nanotube oxygen groups. This competition is a qualitative design principle; no binding constant, ligand-coverage measurement or critical TDPA ratio is established.',2,'Growth rationale',['mechanisms'],'model_context','author_interpretation'),
('site-selectivity','Why oxidation changes the growth sites','Opening tips and etching outer-wall defects is proposed to create oxygen-rich nucleation sites. Figures 2a,d show relatively greater particle density near tips. The authors relate high tip reactivity to curvature and prior acid-etching studies. These interpretations explain the images and oxidation controls but do not quantitatively assign a chemical group to each attached particle or count the removed wall layers.',5,'Microscopy discussion continuing on pp. 6–8',['mechanisms'],'model_context','author_interpretation'),
('diffusion-model','Why some attached crystals are elongated','The source proposes that a bulky MWNT blocks access to one crystallite face, causing monomer to arrive preferentially at the exposed end and favor pseudo-one-dimensional growth. This diffusion-limited steric model, cited to reference 40, is not a measured monomer flux or a fitted growth-rate law.',7,'Elongated crystal discussion',['mechanisms'],'model_context','author_model'),
('shape-variables','Factors proposed to control shape and junctions','The authors propose local functional-group density, site geometry, monomer access and spacing between sites or adjacent tubes as contributors to the broad size/shape distribution. Intertube separation can permit a growing crystal to bridge a gap, yielding a junction; no controlled spacing series or quantitative predictive model is supplied.',8,'Nanocrystal geometry discussion',['mechanisms'],'model_context','author_interpretation'),
('figure8-model','Figure 8: author growth schematic','The original schematic depicts pristine MWNT oxidation, oxygen-group formation, Cd coordination and Te-driven in situ growth, including possible multi-tube junctions. TDPA is omitted for clarity. The illustrated atoms and particle shapes are explanatory, with no unique chirality, wall count, lattice match or measured atomic coordinates implied.',8,'Figure 8',['mechanisms'],'model_context','author_model'),
('passivation-model','Surface-passivation limitation','The authors argue that bulky nanotubes cannot completely cover a CdTe surface, allowing oxidation during prolonged air exposure. Surface decomposition and faster degradation at higher temperatures are discussed without an aging time series or activation-energy measurement.',8,'XPS and passivation discussion',['mechanisms'],'model_context','author_interpretation'),
('thermal-context','Thermal interpretation of surface groups','The source states that heating can remove nanotube carboxyl groups, with complete removal only around 350 °C, while intrinsic nanotube/crystal structures are expected to persist to such temperatures. This discussion is not a characterized 350 °C treatment step, measured thermal-stability bound or recommended storage condition.',8,'Passivation paragraph',['mechanisms'],'model_context','author_interpretation'),
('detachment-model','Possible origin of heterogeneous washings','The authors propose that some nanocrystals become detached at different stages of tube-influenced growth, accounting for less uniform washings than a no-tube reference. This is a postulated mechanism, not a directly observed detachment movie or a new independently specified recipe.',9,'Electronic spectrum discussion',['mechanisms','free-nanocrystals'],'model_context','author_interpretation'),
('mwnt-swnt','Why the study uses multiwalled nanotubes','The conclusion notes difficulty creating enough oxygenated sites on single-walled tubes with conventional oxidation while preserving structural/electronic integrity. Improved oxidative control is proposed for more sophisticated assemblies. No successful equivalent SWNT recipe is provided.',9,'Conclusions',['mechanisms'],'model_context','author_interpretation'),
('quantum-confinement','Quantum-confinement interpretation','The authors regard the small CdTe crystallites and shifted/broadened LO Raman response as consistent with confined clusters. This interpretation is distinct from a resolved excitonic absorption energy, an experimentally measured bandgap or a validated electronic-structure calculation.',8,'Raman discussion and p. 9 conclusion',['mechanisms'],'model_context','author_interpretation'),
('outlook','Proposed follow-up experiments','Proposed work includes charge transport through junctions, growth across aligned nanotubes and composite thin films. Generalization to other binary or complex nanocrystals and insight into oriented attachment are prospective. The hoped-for control of electronic structure, trapping, delocalization and charge separation motivates photovoltaic interest; none of these device outcomes is established by this paper.',2,'Introduction and p. 9 outlook',['source-context'],'cited_context','source_outlook'),
])
rows('sources',[
('identity','Article identity','Sarbajit Banerjee and Stanislaus S. Wong, In Situ Quantum Dot Growth on Multiwalled Carbon Nanotubes, Journal of the American Chemical Society 2003, 125(34), 10342–10350, DOI 10.1021/ja035980c. Received May 6, 2003; published on the web July 31, 2003. The publication year is 2003, correcting the local index’s heuristic 2002 entry.',1,'Title, byline and journal footer',['source-context'],'source_metadata','verified_source_identity'),
('source-context','Affiliations and administrative context','The authors are affiliated with SUNY at Stony Brook Chemistry and Brookhaven National Laboratory Materials and Chemical Sciences. Wong is the corresponding author. The PDF download watermark and malformed embedded creation metadata are administrative and do not set the publication year.',1,'Byline, footnotes and watermark',['source-context'],'source_metadata','source_metadata'),
('si-identity','Main–SI identity matching','The main article explicitly announces an infrared spectrum of oxidized multiwalled nanotubes. The supplied one-page SI uses that same subject in its heading and its PDF Title contains ja035980csi20030625_041651.doc. These agree in manuscript identifier and scientific content. The SI has no independently printed full article title or DOI on the page; that limitation is retained.',9,'Supporting Information declaration',['source-context'],'source_metadata','verified_source_identity'),
('coverage','Complete supplied-source coverage','All nine main pages and the matched one-page SI were read and visually inspected, including eight numbered main figures, the SI infrared plot, every caption, methods, discussions and all 43 reference entries. No table or numbered equation is present. Original curves and micrographs are retained rather than reconstructed.',9,'Complete supplied source',['source-context'],'source_metadata','reviewed_source_coverage'),
('missing-fields','Recipe completeness limits','The article omits precursor masses, stock concentrations, most liquid volumes, oxidation durations, several temperatures, injected quantity, injection rate, heating ramps, final drying conditions, isolated yield and storage. Reference 35 and the modified Peng procedures identify method provenance but do not fill these missing fields without separately reading those sources.',2,'Experimental Section',['source-context'],'curator_interpretation','reviewed_source_limitation'),
('sample-boundaries','Specimen-association limits','Pristine/processed nanotubes, heterostructures, mild-oxidation controls, free washings and no-tube comparators remain separate source cohorts. Shared study context does not establish that all images and spectra came from one physical batch. Figure 3a’s inset is explicitly a different composite; SI IR is precursor-only.',5,'Figure 3a caption, methods and comparison discussion',['source-context'],'curator_interpretation','curation_scope'),
('data-precision','Curve and model provenance','Source spectra are qualitative plotted evidence unless a value is stated explicitly. No dense digitized trace, peak fit, particle-by-particle distribution, exact chemical formula of the oxidized surface or atom-coordinate reconstruction is invented. The EDS energy-unit ambiguity and literal TeO₃ attribution are preserved.',6,'Figures 4–8 and SI',['source-context'],'curator_interpretation','curation_scope'),
('reference-scope','Cited literature scope','All 43 numbered reference entries are preserved for traceability. Their external documents were not independently opened as part of this review. Contextual mention of other materials, nanotube routes or devices does not create new synthesis data points.',1,'References across pp. 1–9',['source-context'],'cited_context','external_reference_scope'),
('funding','Acknowledgments','The source acknowledges SUNY Stony Brook and Brookhaven startup support, ACS Petroleum Research Fund donors, and a 3M nontenured faculty award. It credits Jianyu Huang and James Quinn for microscopy assistance, Craig Silverman for Raman work, and Drew Hirt for XPS work.',9,'Acknowledgment',['source-context'],'source_metadata','source_metadata'),
])
more('si-identity',1,'Heading and full infrared plot',role='si')
